import json, re
from pathlib import Path
from collections import defaultdict
p = Path(r'C:/Users/phant/.grok/sessions/E%3A%5CAIdle_openworld/019f830a-e077-7761-9be6-4fedb4a3f69c/chat_history.jsonl')
