kind_ord = defaultdict(int)
calls = []
# scan assistant messages for tool uses
for li, line in enumerate(raw_lines, 1):
    obj = json.loads(line)
    if obj.get('type') != 'assistant':
        continue
    content = obj.get('content')
    # content may be list or string
    items = content if isinstance(content, list) else []
    for part in items:
        if not isinstance(part, dict):
            continue
        ptype = part.get('type')
        if ptype in ('tool_use','function_call','tool_call','toolCall'):
            print('FOUND', ptype, list(part.keys()))
            print(json.dumps(part)[:800])
    # also check top-level tool_calls
    if 'tool_calls' in obj:
        print('TOP_TOOL_CALLS', obj['tool_calls'][:1])
# print a full assistant message structure
for li, line in enumerate(raw_lines, 1):
    obj = json.loads(line)
    if obj.get('type')=='assistant':
        print('ASSISTANT_KEYS', obj.keys())
        c=obj.get('content')
        print('CONTENT_TYPE', type(c).__name__)
        if isinstance(c,str):
            print('STR_PREFIX', c[:400])
        elif isinstance(c,list):
            for part in c[:5]:
                if isinstance(part, dict):
                    print('PART', part.get('type'), list(part.keys()))
                else:
                    print('PART_T', type(part))
        break
# tool_result sample
for li, line in enumerate(raw_lines, 1):
